import 'dart:convert';
import 'dart:typed_data';

import 'api_login_helper.dart';

/// A plain 320x240 PNG.
ReceiverMediaFile imageFixture(String name) => ReceiverMediaFile(
  name: name,
  bytes: base64Decode(
    '',
  ),
  mimeType: 'image/png',
  info: const {'w': 320, 'h': 240},
);

const videoFixtureDuration = Duration(seconds: 2);

/// A 2-second 160x120 H.264 clip.
ReceiverMediaFile videoFixture(String name) => ReceiverMediaFile(
  name: name,
  bytes: base64Decode(
    '',
  ),
  mimeType: 'video/mp4',
  info: {'w': 160, 'h': 120, 'duration': videoFixtureDuration.inMilliseconds},
  // Real clients send a thumbnail, so the bubble does not fetch the video.
  thumbnail: imageFixture('$name.png'),
);

final _onePagePdf = base64Decode(
  '',
);

/// A one-page PDF. [paddedTo] grows it with a trailing comment, which PDF
/// readers ignore, so several downloads overlap.
ReceiverMediaFile pdfFixture(String name, {int paddedTo = 0}) {
  final padding = paddedTo - _onePagePdf.length;
  return ReceiverMediaFile(
    name: name,
    bytes: padding <= 0
        ? _onePagePdf
        : Uint8List.fromList([
            ..._onePagePdf,
            ...utf8.encode('%'),
            ...List.filled(padding - 1, 0x20),
          ]),
    mimeType: 'application/pdf',
  );
}
